-- ELECTRIC BIKES & ADVANCED MOBILITY (8 products)
('radpower-radcity-7-plus', 'Rad Power Bikes RadCity 7 Plus Step-Thru Electric Bike - Charcoal', 'e-mobility', 850000, 829000, 720000, 4, 29.5, '/assets/products/radcity-7-plus.jpg', 'The ultimate Nigerian city commuter with a step-thru frame for effortless mounting. The 750W geared hub motor conquers hills with ease, the 672Wh battery delivers 80km range, and integrated lights, fenders, and a rear rack come standard for year-round utility.', 1, unixepoch('2026-06-16'), 1, 720000, '/assets/products/radcity-7-plus.jpg', 780000, 4.7, 1, 'Rad Power Bikes', 1, 1),

('aventon-sinch-3-folding', 'Aventon Sinch.3 Folding Fat Tire Electric Bike - Midnight Black', 'e-mobility', 750000, 729000, 635000, 5, 30.5, '/assets/products/aventon-sinch-3.jpg', 'A full-suspension fat tire e-bike that folds for storage in your apartment or car trunk. The 4-inch wide tires absorb potholes and rough roads, the 750W motor pushes 28mph, and the torque sensor provides a natural, intuitive pedaling feel.', 1, unixepoch('2026-06-16'), 1, 635000, '/assets/products/aventon-sinch-3.jpg', 695000, 4.6, 0, 'Aventon', 1, 1),

('lectric-xp-4-long-range', 'Lectric XP 4.0 Long-Range Folding Electric Bike with Hydraulic Brakes', 'e-mobility', 580000, 569000, 495000, 6, 28.0, '/assets/products/lectric-xp-4.jpg', 'America''s bestselling e-bike gets a massive upgrade with hydraulic disc brakes, a 100km long-range battery, and a foldable frame that collapses in seconds. The 750W motor with 5 pedal-assist levels and twist throttle makes any commute effortless.', 1, unixepoch('2026-06-16'), 1, 495000, '/assets/products/lectric-xp-4.jpg', 535000, 4.5, 1, 'Lectric', 1, 1),

('super73-s-adventure-series', 'Super73-S Adventure Series Electric Motorbike - Panthro Blue', 'e-mobility', 1250000, 1215000, 1050000, 3, 36.0, '/assets/products/super73-s-adventure.jpg', 'A head-turning electric motorbike with scrambler styling. The S-Adventure features a 2,000W peak motor, full motorcycle-grade suspension, a removable 960Wh battery, and rugged tires that handle both paved roads and off-road trails with style.', 1, unixepoch('2026-06-16'), 1, 1050000, '/assets/products/super73-s-adventure.jpg', 1150000, 4.7, 0, 'Super73', 1, 1),

('segway-cube-3000-scooter', 'Segway Cube 3000 Electric Kick Scooter 65km Range - Space Grey', 'e-mobility', 450000, 439000, 380000, 6, 21.5, '/assets/products/segway-cube-3000.jpg', 'Segway''s most powerful kick scooter with a 500W motor, 10.5-inch pneumatic tires for rough roads, and an industry-leading 65km range. Triple braking system with electronic front, drum rear, and foot brake ensures confident stopping in Nigerian traffic.', 1, unixepoch('2026-06-16'), 1, 380000, '/assets/products/segway-cube-3000.jpg', 415000, 4.6, 1, 'Segway', 1, 1),

('himoto-cargo-e-bike', 'Himoto Cargo Electric Bike with Front Basket & Child Seat Ready', 'e-mobility', 380000, 369000, 315000, 5, 27.0, '/assets/products/himoto-cargo.jpg', 'The family-friendly electric cargo bike built for Nigerian market runs. The extended rear rack supports a child seat or cargo, the 350W motor assists with heavy loads, and the included front basket handles groceries. A practical, affordable car replacement.', 1, unixepoch('2026-06-16'), 1, 315000, '/assets/products/himoto-cargo.jpg', 348000, 4.3, 1, 'Himoto', 1, 1),

('philodo-h8-dual-motor', 'Philodo H8 Dual Motor 2000W Fat Tire Electric Bike - Forest Green', 'e-mobility', 650000, 639000, 555000, 4, 32.0, '/assets/products/philodo-h8.jpg', 'Dual 1000W motors deliver all-wheel-drive traction and incredible 35mph top speed. The 48V 23Ah battery provides 90km range, while the hydraulic brakes with 203mm rotors and dual suspension tame the power for confident control on any terrain.', 1, unixepoch('2026-06-16'), 1, 555000, '/assets/products/philodo-h8.jpg', 605000, 4.5, 0, 'Philodo', 1, 1),

('jetbolt-pro-folding-e-bike', 'Jetbolt Pro Compact Folding Electric Bike with 48V Battery - Ivory White', 'e-mobility', 320000, 315000, 268000, 6, 22.5, '/assets/products/jetbolt-pro.jpg', 'An ultra-compact folding e-bike that weighs just 19kg yet carries riders up to 120kg. The 350W motor assists up to 25km/h with a 50km range, and the 14-inch wheels with fat tires provide surprising stability for such a portable package.', 1, unixepoch('2026-06-16'), 1, 268000, '/assets/products/jetbolt-pro.jpg', 298000, 4.4, 1, 'Jetbolt', 1, 1),

-- PERSONAL CARE & GROOMING TECH (10 products)
('dyson-airwrap-id-styler', 'Dyson Airwrap i.d. Multi-Styler with Bluetooth & Curl Recognition', 'personal-care', 480000, 469000, 410000, 6, 2.8, '/assets/products/dyson-airwrap-id.jpg', 'The Airwrap that knows your hair. Bluetooth connects to the MyDyson app where you input your hair profile, and the styler automatically adjusts heat and airflow for your specific hair type. i.d. curl recognition personalizes the direction and timing of each curl.', 1, unixepoch('2026-06-16'), 1, 410000, '/assets/products/dyson-airwrap-id.jpg', 438000, 4.7, 1, 'Dyson', 1, 1),

