('shark-flexstyle-2-air-styler', 'Shark FlexStyle 2 Air Styling & Drying System - Stone', 'personal-care', 250000, 245000, 215000, 8, 2.1, '/assets/products/shark-flexstyle-2.jpg', 'A complete styling system that transforms from a powerful hair dryer into a multi-styler. The rotating nozzle auto-wraps hair for perfect curls, while the oval brush smooths and volumizes. Coanda technology styles with air, not extreme heat.', 1, unixepoch('2026-06-16'), 1, 215000, '/assets/products/shark-flexstyle-2.jpg', 235000, 4.6, 1, 'Shark', 1, 1),

('withings-beamO-multiscope', 'Withings BeamO 4-in-1 Health Multiscope - Thermometer/Stethoscope/Oximeter/ECG', 'personal-care', 185000, 179000, 148000, 10, 0.15, '/assets/products/withings-beamo.jpg', 'Four essential health tools in one compact device that guides you with a color screen. Measure temperature, listen to heart and lung sounds, check blood oxygen, and record a medical-grade ECG. Results sync instantly to the Withings app for doctor sharing.', 1, unixepoch('2026-06-16'), 1, 148000, '/assets/products/withings-beamo.jpg', 168000, 4.7, 1, 'Withings', 1, 1),

('nooro-foot-massager-pro', 'Nooro Pro 3-in-1 Foot Massager with Heat & EMS Therapy - Grey', 'personal-care', 125000, 119000, 98000, 10, 2.8, '/assets/products/nooro-foot-pro.jpg', 'Relieve tired feet with kneading massage, EMS muscle stimulation, and soothing heat. The full-coverage design massages heels, arches, and toes simultaneously, with 5 intensity levels that work out tension after long commutes and standing all day.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/nooro-foot-pro.jpg', 112000, 4.5, 1, 'Nooro', 1, 1),

('olaplex-hair dryer-pro', 'Olaplex Professional Hair Dryer with Bond-Building Technology - White', 'personal-care', 250000, 245000, 215000, 6, 1.85, '/assets/products/olaplex-dryer.jpg', 'The first hair dryer that repairs hair while it dries. Olaplex''s patented bond-building technology is integrated into the airflow, actively repairing broken disulfide bonds during styling. The brushless motor delivers 110,000 RPM for fast, frizz-free results.', 1, unixepoch('2026-06-16'), 1, 215000, '/assets/products/olaplex-dryer.jpg', 235000, 4.7, 0, 'Olaplex', 1, 1),

('emma-sleep-motion-pillow', 'Emma Motion Smart Pillow with Sleep Tracking & Position Adjustment', 'personal-care', 165000, 159000, 132000, 8, 1.8, '/assets/products/emma-motion-pillow.jpg', 'A pillow that actively improves your sleep. Built-in sensors detect snoring and gently adjust the pillow''s height to open your airway without waking you. The companion app provides detailed sleep analysis and tracks improvement over time.', 1, unixepoch('2026-06-16'), 1, 132000, '/assets/products/emma-motion-pillow.jpg', 149000, 4.4, 0, 'Emma Sleep', 1, 1),

('panasonic-lumix-beauty-mirror', 'Panasonic Lumix Smart Beauty Mirror with Skin Analysis & LED Lighting', 'personal-care', 220000, 215000, 178000, 5, 3.2, '/assets/products/panasonic-beauty-mirror.jpg', 'Your personal skincare consultant. The high-resolution camera analyzes pores, wrinkles, and skin tone, recommending products and routines. The LED ring light simulates office, evening, and natural daylight so your makeup looks perfect in every setting.', 1, unixepoch('2026-06-16'), 1, 178000, '/assets/products/panasonic-beauty-mirror.jpg', 205000, 4.5, 0, 'Panasonic', 1, 1),

