('arduino-uno-r5-wifi-kit', 'Arduino UNO R5 WiFi Complete Starter Kit with 45 Sensors & Modules', 'stem-education', 85000, 82900, 68000, 12, 1.25, '/assets/products/arduino-uno-r5-kit.jpg', 'The definitive starting point for electronics and programming. This comprehensive kit includes the powerful UNO R5 board with WiFi and Bluetooth, 45 sensors and actuators, and a detailed project book with 25 step-by-step tutorials that progress from LED blinking to IoT.', 1, unixepoch('2026-06-16'), 1, 68000, '/assets/products/arduino-uno-r5-kit.jpg', 78000, 4.7, 1, 'Arduino', 1, 1),

('raspberry-pi-6-model-b', 'Raspberry Pi 6 Model B 8GB Single-Board Computer with WiFi 7', 'stem-education', 65000, 63900, 52000, 10, 0.05, '/assets/products/raspberry-pi-6.jpg', 'The most powerful Raspberry Pi ever, now with a quad-core ARM Cortex-A78 processor, 8GB LPDDR5 RAM, dual 4K HDMI outputs, and WiFi 7. Perfect for coding, home servers, media centers, and learning Linux—the possibilities are endless.', 1, unixepoch('2026-06-16'), 1, 52000, '/assets/products/raspberry-pi-6.jpg', 59000, 4.8, 1, 'Raspberry Pi', 1, 1),

('elegoo-neptune-5-pro-3d-printer', 'Elegoo Neptune 5 Pro FDM 3D Printer with Direct Drive & Auto-Leveling', 'stem-education', 250000, 245000, 215000, 5, 12.5, '/assets/products/elegoo-neptune-5.jpg', 'Your gateway into 3D printing with professional features at a hobbyist price. The direct drive extruder handles flexible filaments, the 49-point auto bed leveling ensures perfect first layers, and the 300°C hotend prints PLA, PETG, TPU, and ABS with ease.', 1, unixepoch('2026-06-16'), 1, 215000, '/assets/products/elegoo-neptune-5.jpg', 235000, 4.6, 1, 'Elegoo', 1, 1),

('microbit-v3-club-kit', 'BBC micro:bit V3 Club Kit 10-Pack with Sensors & Batteries', 'stem-education', 125000, 119000, 98000, 8, 1.5, '/assets/products/microbit-v3-kit.jpg', 'Equip an entire classroom or coding club with 10 micro:bit V3 boards featuring a built-in speaker, microphone, and touch sensor. The kit includes battery holders, USB cables, and access to Microsoft MakeCode for block-based or Python programming.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/microbit-v3-kit.jpg', 112000, 4.7, 0, 'BBC', 1, 1),

('dj-robomaster-s2', 'DJI RoboMaster S2 Intelligent Coding Robot with AI Camera', 'stem-education', 380000, 369000, 315000, 4, 3.5, '/assets/products/dji-robomaster-s2.jpg', 'A battle-ready educational robot that teaches coding through competitive play. The omnidirectional Mecanum wheels, gel bead blaster, and AI-powered computer vision camera let you program autonomous combat and racing behaviors in Scratch or Python.', 1, unixepoch('2026-06-16'), 1, 315000, '/assets/products/dji-robomaster-s2.jpg', 348000, 4.6, 0, 'DJI', 1, 1),

('snap-circuits-arcade-pro', 'Snap Circuits Arcade Pro 200-in-1 Electronics Exploration Kit', 'stem-education', 65000, 63900, 52000, 10, 1.8, '/assets/products/snap-circuits-arcade.jpg', 'Build 200 working electronic projects including a programmable word fan, tri-color light orb, and dual LED display. No soldering required—components snap together on the grid. Winner of multiple toy-of-the-year awards for ages 8 and up.', 1, unixepoch('2026-06-16'), 1, 52000, '/assets/products/snap-circuits-arcade.jpg', 59000, 4.7, 0, 'Snap Circuits', 1, 1),

('knex-education-stem-building', 'K''NEX Education STEM Explorations Building Set 800-Piece', 'stem-education', 38000, 36900, 30500, 10, 2.5, '/assets/products/knex-stem-building.jpg', '800 colorful rods, connectors, and gears that bring engineering concepts to life. Build working models of bridges, vehicles, and machines while learning principles of mechanics, structural design, and physics through hands-on experimentation for ages 8-16.', 1, unixepoch('2026-06-16'), 1, 30500, '/assets/products/knex-stem-building.jpg', 34800, 4.5, 0, 'K''NEX', 1, 1),

('petoi-bittle-x-robot-dog', 'Petoi Bittle X Programmable Robot Dog with Camera & Voice Control', 'stem-education', 250000, 245000, 215000, 5, 0.35, '/assets/products/petoi-bittle-x.jpg', 'A lifelike robot dog that teaches coding from beginner to advanced. Program movements in Scratch-like blocks, control via voice commands, or code advanced behaviors in C++ and Python. The open-source design with 3D-printable parts invites endless customization.', 1, unixepoch('2026-06-16'), 1, 215000, '/assets/products/petoi-bittle-x.jpg', 235000, 4.5, 0, 'Petoi', 1, 1),

