('ecobee-smart-sensor-premium', 'ecobee SmartSensor Premium 2-Pack for Doors & Windows with Motion', 'smart-home', 65000, 63900, 52000, 12, 0.08, '/assets/products/ecobee-sensor-premium.jpg', 'Extend your ecobee thermostat''s intelligence to every room. These sensors detect occupancy, temperature, and door/window status, enabling room-specific comfort and automated alerts if a door is left open. Easy peel-and-stick installation with 5-year battery life.', 1, unixepoch('2026-06-16'), 1, 52000, '/assets/products/ecobee-sensor-premium.jpg', 59000, 4.5, 0, 'ecobee', 1, 1),

('leviton-smart-load-center', 'Leviton Smart Load Center with WiFi Circuit Breakers - 200A Panel', 'smart-home', 850000, 829000, 720000, 2, 18.0, '/assets/products/leviton-load-center.jpg', 'Complete visibility and control over your home''s entire electrical system. Monitor energy consumption per circuit, receive alerts for abnormal power draw, and remotely control individual breakers. A professional electrician-installed upgrade for the connected home.', 1, unixepoch('2026-06-16'), 1, 720000, '/assets/products/leviton-load-center.jpg', 780000, 4.6, 0, 'Leviton', 1, 1),

