('blink-outdoor-4-floodlight', 'Blink Outdoor 4 Floodlight Camera Wire-Free 2600 Lumen - Black', 'smart-home', 95000, 92900, 78000, 10, 0.85, '/assets/products/blink-floodlight-4.jpg', 'Brilliant 2,600-lumen LED floodlights with a wire-free Blink camera built in. The two-year battery life, 1080p HD live view, two-way talk, and customizable motion zones provide comprehensive security without running a single wire.', 1, unixepoch('2026-06-16'), 1, 78000, '/assets/products/blink-floodlight-4.jpg', 88000, 4.5, 1, 'Blink', 1, 1),

('vesync-smart-air-quality-monitor', 'VeSync Smart Air Quality Monitor PM2.5/CO2/TVOC with WiFi - White', 'smart-home', 45000, 43900, 36500, 12, 0.25, '/assets/products/vesync-air-monitor.jpg', 'Know exactly what you''re breathing in your home. This sleek monitor tracks particulate matter, carbon dioxide, volatile organic compounds, temperature, and humidity in real-time, with a color-coded LED ring and app notifications when air quality deteriorates.', 1, unixepoch('2026-06-16'), 1, 36500, '/assets/products/vesync-air-monitor.jpg', 41500, 4.4, 0, 'VeSync', 1, 1),

