('universal-audio-apollo-twin-x5', 'Universal Audio Apollo Twin X5 Thunderbolt Audio Interface - Heritage Edition', 'audio', 850000, 829000, 720000, 3, 1.35, '/assets/products/ua-apollo-twin-x5.jpg', 'The gold standard in desktop audio interfaces. The Apollo Twin X5 features elite-class 24-bit/192kHz conversion, two Unison-enabled preamps that emulate classic analog hardware, and a HEXA-core DSP that runs UAD plugins with near-zero latency for recording.', 1, unixepoch('2026-06-16'), 1, 720000, '/assets/products/ua-apollo-twin-x5.jpg', 780000, 4.9, 0, 'Universal Audio', 1, 1),

('focusrite-scarlett-4i4-gen-5', 'Focusrite Scarlett 4i4 5th Gen USB Audio Interface with Air Mode', 'audio', 220000, 215000, 178000, 6, 0.85, '/assets/products/focusrite-4i4-5.jpg', 'The world''s bestselling interface gets a massive overhaul with 4th-gen mic preamps delivering 69dB of gain, Auto Gain that sets perfect levels instantly, and Clip Safe that prevents distortion. Air mode adds the character of a classic Focusrite console.', 1, unixepoch('2026-06-16'), 1, 178000, '/assets/products/focusrite-4i4-5.jpg', 205000, 4.7, 1, 'Focusrite', 1, 1),

('rode-nt1-signature-series', 'RØDE NT1 Signature Series Large-Diaphragm Condenser Microphone - Pink', 'audio', 185000, 179000, 148000, 6, 0.95, '/assets/products/rode-nt1-signature.jpg', 'The world''s quietest studio microphone at just 4dBA self-noise—so silent you can hear a pin drop. The HF6 gold-sputtered capsule captures vocals and instruments with stunning detail, while the shock mount and pop filter are included for professional results out of the box.', 1, unixepoch('2026-06-16'), 1, 148000, '/assets/products/rode-nt1-signature.jpg', 168000, 4.8, 1, 'RØDE', 1, 1),

('beyerdynamic-dt-900-pro-x', 'Beyerdynamic DT 900 PRO X Open-Back Studio Reference Headphones', 'audio', 250000, 245000, 215000, 5, 0.35, '/assets/products/beyerdynamic-dt900x.jpg', 'The open-back mixing and mastering reference trusted in studios worldwide. The STELLAR.45 driver delivers a natural, spacious soundstage with surgical precision, while the 48-ohm impedance and detachable cable make them equally at home with audio interfaces and mobile devices.', 1, unixepoch('2026-06-16'), 1, 215000, '/assets/products/beyerdynamic-dt900x.jpg', 235000, 4.8, 0, 'Beyerdynamic', 1, 1),

('adam-audio-t8v-monitors', 'ADAM Audio T8V Active Studio Monitor Speakers Pair - Black', 'audio', 480000, 469000, 410000, 3, 12.5, '/assets/products/adam-t8v.jpg', 'German-engineered studio monitors featuring ADAM''s signature X-ART ribbon tweeter for breathtaking transient response and an 8-inch woofer that extends bass to 33Hz. The HPS waveguide creates a wide sweet spot for accurate mixing in any room.', 1, unixepoch('2026-06-16'), 1, 410000, '/assets/products/adam-t8v.jpg', 438000, 4.8, 0, 'ADAM Audio', 1, 1),

('shure-mv8-usb-microphone', 'Shure MV8 USB Podcast Microphone with Voice Isolation & Onboard DSP', 'audio', 125000, 119000, 98000, 8, 0.65, '/assets/products/shure-mv8.jpg', 'Broadcast-quality audio with the simplicity of USB-C plug-and-play. The MV8 features Shure''s Voice Isolation technology that rejects background noise, a built-in DSP with EQ, compressor, and limiter, and a headphone output for zero-latency monitoring.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/shure-mv8.jpg', 112000, 4.6, 1, 'Shure', 1, 1),

('native-instruments-kontrol-s88-mk4', 'Native Instruments Komplete Kontrol S88 MK4 Smart Keyboard Controller', 'audio', 850000, 829000, 720000, 2, 15.5, '/assets/products/ni-kontrol-s88.jpg', 'The definitive 88-key weighted hammer-action controller for composers. Polyphonic aftertouch, a full-color touchscreen, and deep integration with Komplete software and major DAWs make this the centerpiece of any professional music production studio.', 1, unixepoch('2026-06-16'), 1, 720000, '/assets/products/ni-kontrol-s88.jpg', 780000, 4.8, 0, 'Native Instruments', 1, 1),

