('whistle-go-explore-3', 'Whistle GO Explore 3 GPS Pet Tracker with Health Monitoring - Green', 'pet-tech', 85000, 82900, 68000, 10, 0.03, '/assets/products/whistle-go-3.jpg', 'Know where your pet is and how healthy they are. The GO Explore 3 uses GPS, WiFi, and cellular triangulation for the most accurate tracking, while monitoring scratching, licking, and sleeping patterns to detect potential health issues before they become serious.', 1, unixepoch('2026-06-16'), 1, 68000, '/assets/products/whistle-go-3.jpg', 78000, 4.5, 0, 'Whistle', 1, 1),

('litter-robot-5-connect', 'Litter-Robot 5 Connect WiFi Self-Cleaning Cat Litter Box - Grey', 'pet-tech', 480000, 469000, 410000, 3, 14.5, '/assets/products/litter-robot-5.jpg', 'Never scoop litter again with the quietest, most advanced self-cleaning box. The patented sifting system separates waste into a sealed drawer, while the app tracks your cat''s weight, bathroom habits, and health trends. Whisker Insight alerts you to potential UTIs or issues.', 1, unixepoch('2026-06-16'), 1, 410000, '/assets/products/litter-robot-5.jpg', 438000, 4.7, 0, 'Litter-Robot', 1, 1),

('petkit-pura-x-automatic-box', 'PETKIT Pura X Self-Cleaning Smart Cat Litter Box with App - White', 'pet-tech', 320000, 315000, 268000, 4, 10.5, '/assets/products/petkit-pura-x.jpg', 'A fully automated litter box that uses the xSecure safety system with infrared sensors, weight detection, and accident protection to ensure your cat''s absolute safety. The app-controlled deodorizing system and large 7L waste bin mean less maintenance.', 1, unixepoch('2026-06-16'), 1, 268000, '/assets/products/petkit-pura-x.jpg', 298000, 4.5, 1, 'PETKIT', 1, 1),

('wagz-freedom-smart-collar', 'Wagz Freedom Smart Dog Collar with Geofence & Training Tones - Black', 'pet-tech', 125000, 119000, 98000, 8, 0.22, '/assets/products/wagz-freedom-collar.jpg', 'Create a wireless fence anywhere with GPS geofencing that triggers a warning tone if your dog approaches the boundary. The collar also features activity tracking, LED safety lights for night walks, and training tone modes for positive reinforcement.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/wagz-freedom-collar.jpg', 112000, 4.4, 0, 'Wagz', 1, 1),

('catlink-young-automatic-feeder', 'Catlink Young Automatic Pet Feeder with App & Dual Food Tray - White', 'pet-tech', 85000, 82900, 68000, 10, 1.65, '/assets/products/catlink-young-feeder.jpg', 'Ensure your pets are fed on schedule even when you''re away. The app-controlled feeder dispenses precise portions with a dual-tray design that serves two pets separately. The 4L sealed hopper keeps food fresh, while the backup battery prevents missed meals.', 1, unixepoch('2026-06-16'), 1, 68000, '/assets/products/catlink-young-feeder.jpg', 78000, 4.4, 0, 'Catlink', 1, 1),

('petcube-bites-3-lite', 'Petcube Bites 3 Lite WiFi Pet Camera with Treat Dispenser - Silver', 'pet-tech', 65000, 63900, 52000, 10, 0.55, '/assets/products/petcube-bites-3.jpg', 'Play with your pet from anywhere. The Bites 3 Lite features 1080p video with 4x zoom, two-way audio, and a treat dispenser that flings treats up to 2 meters. Motion and sound alerts notify you when your pet is active, with a built-in laser toy for remote play.', 1, unixepoch('2026-06-16'), 1, 52000, '/assets/products/petcube-bites-3.jpg', 59000, 4.5, 1, 'Petcube', 1, 1),

('garmin-alpha-400-dog-tracker', 'Garmin Alpha 400 GPS Dog Tracking & Training Collar Bundle', 'pet-tech', 450000, 439000, 380000, 3, 0.45, '/assets/products/garmin-alpha-400.jpg', 'Professional-grade tracking and training for hunting, security, and working dogs. The handheld unit tracks up to 20 dogs over 9 miles with topographic maps, while the collar delivers 18 levels of momentary and continuous stimulation with tone and vibration options.', 1, unixepoch('2026-06-16'), 1, 380000, '/assets/products/garmin-alpha-400.jpg', 415000, 4.7, 0, 'Garmin', 1, 1);
